Collector","2026-11-18 03:01:21","2026-11-18 03:07:21"],["2026-11-18|-11038.3,1372","2026-11-18","Páramos de Poniente","Arroyo de la Luna","Páramos de Poniente","Arroyo de la Luna",0,"[[-11038.3, 1372]]","WowdataCollector","2026-11-18 03:01:21","2026-11-18 03:07:21"],["2026-11-18|-11009.7,1368.5","2026-11-18","Páramos de Poniente","Arroyo de la Luna","Páramos de Poniente","Arroyo de la Luna",0,"[[-11009.7, 1368.5], [-11003.3, 1368.9]]","WowdataCollector","2026-11-18 03:01:21","2026-11-18 03:07:21"],["2026-11-18|-10965.8,1360.8","2026-11-18","Páramos de Poniente","Arroyo de la Luna","Páramos de Poniente","Arroyo de la Luna",0,"[[-10965.8, 1360.8], [-10961.2, 1368.3]]","WowdataCollector","2026-11-18 03:01:21","2026-11-18 03:07:21"],["2026-11-18|-8848.8,650.7","2026-11-18","Ciudad de Ventormenta","Distrito de Mercaderes","Ciudad de Ventormenta","Distrito de Mercaderes",0,"[[-8848.8, 650.7]]","WowdataCollector","2026-11-18 03:01:21","2026-11-18 03:07:21"]]}],"views":[{"name":"v_botin","sql":"CREATE VIEW \"v_botin\" AS\n        SELECT npc_id, item_id, veces, muertes, porcentaje, origen FROM (\n            SELECT *, ROW_NUMBER() OVER (PARTITION BY npc_id, item_id ORDER BY prio) AS rn FROM (\n                SELECT npc_id, item_id, veces, muertes, 100.0 * veces / muertes AS porcentaje, 'juego' AS origen, 1 AS prio\n                  FROM obs_wdc_botin WHERE muertes > 0\n                UNION ALL\n                SELECT npc_id, item_id, veces, muertes, 100.0 * veces / muertes, 'juego', 2\n                  FROM obs_botin WHERE muertes > 0\n                UNION ALL\n                SELECT npc_id, item_id, NULL, NULL, percent, 'questie', 3 FROM questie_drop_rate\n                UNION ALL\n                SELECT npc_id, item_id, NULL, NULL, rate_percent, 'externa', 4 FROM ext_item_drop_rates WHERE npc_id IS NOT NULL\n            )\n        ) WHERE rn = 1"},{"name":"v_companero","sql":"CREATE VIEW \"v_companero\" AS\n        SELECT c.item_id, COALESCE(il.name, s.Display_lang_esES, s.Display_lang) AS objeto, c.spell_id,\n               COALESCE(sn.Name_lang_esES, sn.Name_lang) AS hechizo, c.tipo, c.nivel, c.habilidad,\n               c.origen_tipo, c.npc_id, COALESCE(nl.name, n.name) AS npc_nombre, c.quest_id, c.precio, 'forever' AS origen\n          FROM man_companero c\n          LEFT JOIN ItemSparse s ON s.ID = c.item_id\n          LEFT JOIN ext_item_l10n il ON il.item_id = c.item_id AND il.locale = 'esES'\n          LEFT JOIN SpellName sn ON sn.ID = c.spell_id\n          LEFT JOIN questie_npc n ON n.ID = c.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = c.npc_id AND nl.locale = 'esES'"},{"name":"v_desuello","sql":"CREATE VIEW \"v_desuello\" AS\n        WITH cuero AS (\n            SELECT i.ID AS item_id FROM Item i WHERE i.ClassID = 7 AND i.SubclassID = 6\n        ), bestias AS (\n            SELECT npc_id, MIN(origen) AS origen FROM (\n                SELECT d.source_id AS npc_id, 'questie' AS origen FROM questie_item_drop d\n                  JOIN cuero c ON c.item_id = d.item_id WHERE d.source = 'npc'\n                UNION ALL\n                SELECT npc_id, 'juego' FROM obs_desuello) GROUP BY npc_id\n        )\n        SELECT sp.zone_id, ar.AreaName_lang_esES AS zona, b.npc_id,\n               COALESCE(nl.name, n.name) AS nombre, n.name AS nombre_en,\n               n.minLevel AS nivel_min, n.maxLevel AS nivel_max,\n               CASE WHEN n.maxLevel <= 20 THEN MAX(1, (n.maxLevel - 10) * 10) ELSE n.maxLevel * 5 END\n                    AS habilidad_de_desuello_requerida,\n               b.origen\n          FROM bestias b\n          JOIN questie_npc n ON n.ID = b.npc_id AND n.maxLevel > 0\n          JOIN questie_spawn sp ON sp.kind = 'npc' AND sp.entity_id = b.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = b.npc_id AND nl.locale = 'esES'\n          LEFT JOIN AreaTable ar ON ar.ID = sp.zone_id\n         GROUP BY b.npc_id, sp.zone_id"},{"name":"v_entrenador_hechizo","sql":"CREATE VIEW \"v_entrenador_hechizo\" AS\n        SELECT h.npc_id, COALESCE(nl.name, e.nombre_en) AS npc_nombre, e.nombre_en AS npc_nombre_en, e.tipo, e.clase_id,\n               c.Name_male_lang_esES AS clase, e.profesion_id, e.etiqueta, h.spell_id,\n               COALESCE(sn.Name_lang_esES, h.nombre_en) AS hechizo, COALESCE(sn.Name_lang, h.nombre_en) AS hechizo_en,\n               h.rango, h.coste, h.nivel_req, h.habilidad_req, 'forever' AS origen\n          FROM man_entrenador_hechizo h\n          JOIN man_entrenador e ON e.npc_id = h.npc_id\n          LEFT JOIN ChrClasses c ON c.ID = e.clase_id\n          LEFT JOIN SpellName sn ON sn.ID = h.spell_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = h.npc_id AND nl.locale = 'esES'"},{"name":"v_evento","sql":"CREATE VIEW \"v_evento\" AS\n        SELECT e.holiday_id, e.nombre_en, e.inicio_mes, e.inicio_dia, e.fin_mes, e.fin_dia, e.duracion_dias,\n               e.repeticion, e.nota, (SELECT COUNT(*) FROM man_evento_mision m WHERE m.holiday_id = e.holiday_id) AS misiones,\n               'forever' AS origen\n          FROM man_evento e"},{"name":"v_evento_mision","sql":"CREATE VIEW \"v_evento_mision\" AS\n        SELECT m.holiday_id, e.nombre_en AS evento, m.quest_id, q.titulo, q.nivel, m.rol, 'forever' AS origen\n          FROM man_evento_mision m\n          JOIN man_evento e ON e.holiday_id = m.holiday_id\n          LEFT JOIN v_mision q ON q.quest_id = m.quest_id"},{"name":"v_hechizos_clase","sql":"CREATE VIEW \"v_hechizos_clase\" AS \n        SELECT sla.ClassMask AS ClassMask, sla.SkillLine AS SkillLine, sla.Spell AS SpellID,\n               sn.Name_lang AS Name_enUS, sn.Name_lang_esES AS Name_esES,\n               MIN(CASE WHEN sl.SpellLevel > 0 THEN sl.SpellLevel END) AS Level,\n               sla.AcquireMethod AS AcquireMethod\n        FROM SkillLineAbility sla\n        JOIN SkillLine skl ON skl.ID = sla.SkillLine AND skl.CategoryID = 7\n        LEFT JOIN SpellName sn ON sn.ID = sla.Spell\n        LEFT JOIN SpellLevels sl ON sl.SpellID = sla.Spell\n        WHERE sla.ClassMask <> 0\n        GROUP BY sla.ClassMask, sla.SkillLine, sla.Spell, sla.AcquireMethod"},{"name":"v_hechizos_instructor","sql":"CREATE VIEW \"v_hechizos_instructor\" AS \n        SELECT * FROM v_hechizos_clase\n        WHERE AcquireMethod <> 3 AND SkillLine <> 2851\n          AND SpellID NOT IN (SELECT SpellID FROM TraitDefinition WHERE SpellID IS NOT NULL)"},{"name":"v_jefe_botin","sql":"CREATE VIEW \"v_jefe_botin\" AS\n        SELECT b.npc_id, COALESCE(nl.name, n.name) AS jefe, n.name AS jefe_en, j.map_id, mp.MapName_lang AS instancia,\n               j.area_id, b.dificultad_id, d.Name_lang_esES AS dificultad, d.MaxPlayers AS jugadores,\n               b.item_id, COALESCE(il.name, s.Display_lang_esES, s.Display_lang) AS objeto, s.OverallQualityID AS calidad,\n               b.probabilidad, b.cantidad_min, b.cantidad_max, b.grupo, 'forever' AS origen\n          FROM man_jefe_botin b\n          JOIN man_jefe j ON j.npc_id = b.npc_id AND j.dificultad_id = b.dificultad_id\n          LEFT JOIN questie_npc n ON n.ID = b.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = b.npc_id AND nl.locale = 'esES'\n          LEFT JOIN Map mp ON mp.ID = j.map_id\n          LEFT JOIN Difficulty d ON d.ID = b.dificultad_id\n          LEFT JOIN ItemSparse s ON s.ID = b.item_id\n          LEFT JOIN ext_item_l10n il ON il.item_id = b.item_id AND il.locale = 'esES'"},{"name":"v_jefe_mazmorra","sql":"CREATE VIEW \"v_jefe_mazmorra\" AS\n        SELECT e.ID AS encuentro_id, e.MapID AS map_id, m.MapName_lang AS instancia, e.DifficultyID AS dificultad,\n               e.OrderIndex AS orden, e.Name_lang AS nombre_en, e.Name_lang_esES AS nombre,\n               n.ID AS npc_id, s.zone_id, s.x, s.y\n          FROM DungeonEncounter e\n          LEFT JOIN Map m ON m.ID = e.MapID\n          LEFT JOIN questie_npc n ON n.name = e.Name_lang\n          LEFT JOIN questie_spawn s ON s.kind = 'npc' AND s.entity_id = n.ID"},{"name":"v_mazmorra","sql":"CREATE VIEW \"v_mazmorra\" AS\n        SELECT l.ID AS lfg_id, l.Name_lang_esES AS nombre, l.Name_lang AS nombre_en, m.ala,\n               m.nivel_min, m.nivel_max, 'manual' AS origen_niveles,\n               NULLIF(t.MinLevelSquish, 0) AS nivel_cliente, w.nivel_min AS nivel_addon,\n               CASE ar.FactionGroupMask WHEN 2 THEN 'Alianza' WHEN 4 THEN 'Horda' ELSE 'Disputada' END AS faccion\n          FROM LFGDungeons l\n          LEFT JOIN man_mazmorras_niveles m ON m.lfg_id = l.ID\n          LEFT JOIN contenttuning t ON t.ID = l.ContentTuningID\n          LEFT JOIN obs_wdc_lfg w ON w.lfg_id = l.ID\n          LEFT JOIN (SELECT AreaName_lang, MAX(FactionGroupMask) AS FactionGroupMask FROM AreaTable\n                      GROUP BY AreaName_lang) ar ON ar.AreaName_lang = l.Name_lang OR ar.AreaName_lang = 'The ' || l.Name_lang\n         WHERE l.TypeID = 0 AND l.Name_lang_esES NOT LIKE '%Aleat%'"},{"name":"v_mision","sql":"CREATE VIEW \"v_mision\" AS WITH ids AS (SELECT quest_id AS id FROM obs_wdc_quest WHERE quest_id IS NOT NULL UNION SELECT quest_id AS id FROM obs_quest WHERE quest_id IS NOT NULL UNION SELECT quest_id AS id FROM obs_quest_titulo WHERE quest_id IS NOT NULL UNION SELECT ID AS id FROM QuestV2 WHERE ID IS NOT NULL UNION SELECT quest_id AS id FROM (SELECT quest_id, name FROM ext_quest_l10n WHERE locale = 'esES') WHERE quest_id IS NOT NULL UNION SELECT quest_id AS id FROM (SELECT quest_id, group_concat(text, char(10)) AS text FROM (SELECT * FROM ext_quest_objective_text WHERE locale = 'esES' ORDER BY quest_id, line_no) GROUP BY quest_id) WHERE quest_id IS NOT NULL UNION SELECT quest_id AS id FROM (SELECT * FROM obs_wdb_mision WHERE idioma = 'esES') WHERE quest_id IS NOT NULL UNION SELECT quest_id AS id FROM man_mision_es WHERE quest_id IS NOT NULL UNION SELECT ID AS id FROM questie_quest WHERE ID IS NOT NULL UNION SELECT quest_id AS id FROM questie_xp WHERE quest_id IS NOT NULL) SELECT ids.id AS quest_id, COALESCE(s0.titulo, s1.titulo, s2.titulo, s4.name, NULLIF(s6.titulo, ''), s7.titulo, s8.name) AS titulo, COALESCE(CASE WHEN s0.titulo IS NOT NULL THEN 'es' END, CASE WHEN s1.titulo IS NOT NULL THEN 'es' END, CASE WHEN s2.titulo IS NOT NULL THEN 'es' END, CASE WHEN s4.name IS NOT NULL THEN 'es' END, CASE WHEN NULLIF(s6.titulo, '') IS NOT NULL THEN 'es' END, CASE WHEN s7.titulo IS NOT NULL THEN 'es' END, CASE WHEN s8.name IS NOT NULL THEN 'en' END) AS titulo_idioma, COALESCE(NULLIF(s0.nivel, 0), NULLIF(s1.nivel, 0), NULLIF(s8.questLevel, 0), NULLIF(s9.level, 0)) AS nivel, COALESCE(NULLIF(s0.xp, 0), s9.xp) AS xp, COALESCE(s0.zona, s6.zona) AS zona, COALESCE(s0.objetivo, s5.text, NULLIF(s6.objetivo, ''), s7.objetivo, s8.objectivesText) AS objetivo, COALESCE(CASE WHEN s0.objetivo IS NOT NULL THEN 'es' END, CASE WHEN s5.text IS NOT NULL THEN 'es' END, CASE WHEN NULLIF(s6.objetivo, '') IS NOT NULL THEN 'es' END, CASE WHEN s7.objetivo IS NOT NULL THEN 'es' END, CASE WHEN s8.objectivesText IS NOT NULL THEN 'en' END) AS objetivo_idioma, COALESCE(s0.texto, s6.descripcion) AS texto, CASE WHEN s0.quest_id IS NOT NULL THEN 'juego' WHEN s1.quest_id IS NOT NULL THEN 'juego' WHEN s2.quest_id IS NOT NULL THEN 'juego' WHEN s3.ID IS NOT NULL THEN 'db2' WHEN s4.quest_id IS NOT NULL THEN 'externa' WHEN s5.quest_id IS NOT NULL THEN 'externa' WHEN s6.quest_id IS NOT NULL THEN 'juego' WHEN s7.quest_id IS NOT NULL THEN 'forever' WHEN s8.ID IS NOT NULL THEN 'questie' WHEN s9.quest_id IS NOT NULL THEN 'questie' END AS origen FROM ids LEFT JOIN (SELECT * FROM obs_wdc_quest) s0 ON s0.quest_id = ids.id LEFT JOIN (SELECT * FROM obs_quest) s1 ON s1.quest_id = ids.id LEFT JOIN (SELECT * FROM obs_quest_titulo) s2 ON s2.quest_id = ids.id LEFT JOIN (SELECT * FROM QuestV2) s3 ON s3.ID = ids.id LEFT JOIN (SELECT * FROM (SELECT quest_id, name FROM ext_quest_l10n WHERE locale = 'esES')) s4 ON s4.quest_id = ids.id LEFT JOIN (SELECT * FROM (SELECT quest_id, group_concat(text, char(10)) AS text FROM (SELECT * FROM ext_quest_objective_text WHERE locale = 'esES' ORDER BY quest_id, line_no) GROUP BY quest_id)) s5 ON s5.quest_id = ids.id LEFT JOIN (SELECT * FROM (SELECT * FROM obs_wdb_mision WHERE idioma = 'esES')) s6 ON s6.quest_id = ids.id LEFT JOIN (SELECT * FROM man_mision_es) s7 ON s7.quest_id = ids.id LEFT JOIN (SELECT * FROM questie_quest) s8 ON s8.ID = ids.id LEFT JOIN (SELECT * FROM questie_xp) s9 ON s9.quest_id = ids.id"},{"name":"v_mision_npc","sql":"CREATE VIEW \"v_mision_npc\" AS\n        WITH juego AS (\n            SELECT quest_id, npc_id, CASE rol WHEN 'ofrece' THEN 'dador' ELSE rol END AS rol FROM obs_wdc_quest_npc\n            UNION\n            SELECT quest_id, CAST(dador AS INTEGER), 'dador' FROM obs_quest_dador WHERE dador GLOB '[0-9]*'\n        ),\n        wowhead AS (\n            SELECT DISTINCT quest_id, dador_id AS npc_id, 'dador' AS rol FROM ext_wh_mision_mazmorra\n             WHERE dador_tipo = 'npc' AND dador_id IS NOT NULL\n               AND NOT EXISTS (SELECT 1 FROM juego j WHERE j.quest_id = ext_wh_mision_mazmorra.quest_id\n                                  AND j.rol = 'dador')\n        )\n        SELECT quest_id, npc_id, rol, 'juego' AS origen FROM juego\n        UNION ALL\n        SELECT quest_id, npc_id, rol, 'wowhead' FROM wowhead\n        UNION ALL\n        SELECT q.quest_id, q.entity_id, CASE q.role WHEN 'start' THEN 'dador' ELSE 'entrega' END, 'questie'\n          FROM questie_quest_giver q\n         WHERE q.source = 'npc'\n           AND NOT EXISTS (SELECT 1 FROM juego j WHERE j.quest_id = q.quest_id\n                              AND j.rol = CASE q.role WHEN 'start' THEN 'dador' ELSE 'entrega' END)\n           AND NOT (q.role = 'start' AND EXISTS (SELECT 1 FROM wowhead w WHERE w.quest_id = q.quest_id))"},{"name":"v_mision_requisito","sql":"CREATE VIEW \"v_mision_requisito\" AS\n        SELECT r.quest_id, r.nivel_req AS nivel_requerido,\n               (SELECT group_concat(raza_id) FROM (SELECT raza_id FROM man_mision_raza WHERE quest_id = r.quest_id ORDER BY raza_id)) AS razas,\n               (SELECT group_concat(clase_id) FROM (SELECT clase_id FROM man_mision_clase WHERE quest_id = r.quest_id ORDER BY clase_id)) AS clases,\n               (SELECT group_concat(otra_quest_id) FROM (SELECT otra_quest_id FROM man_mision_relacion WHERE quest_id = r.quest_id AND tipo = 'previa' ORDER BY 1)) AS previas,\n               (SELECT group_concat(otra_quest_id) FROM (SELECT otra_quest_id FROM man_mision_relacion WHERE quest_id = r.quest_id AND tipo = 'previa_alguna' ORDER BY 1)) AS previas_alguna,\n               (SELECT group_concat(otra_quest_id) FROM (SELECT otra_quest_id FROM man_mision_relacion WHERE quest_id = r.quest_id AND tipo = 'excluyente' ORDER BY 1)) AS excluyentes,\n               r.siguiente AS siguiente_cadena, r.habilidad_id, r.habilidad_valor,\n               (SELECT group_concat(faccion_id || ':' || valor) FROM (SELECT faccion_id, valor FROM man_mision_reputacion WHERE quest_id = r.quest_id ORDER BY faccion_id)) AS reputacion_recompensa,\n               r.rep_al_entregar, 'forever' AS origen\n          FROM man_mision_req r\n        UNION ALL\n        SELECT q.ID, q.requiredLevel, NULL, NULL,\n               NULLIF(trim(COALESCE(q.preQuestSingle, '') || COALESCE(q.preQuestGroup, ''), '[]'), ''), NULL, NULL,\n               q.nextQuestInChain, NULL, NULL, NULL, NULL, 'questie'\n          FROM questie_quest q WHERE q.ID NOT IN (SELECT quest_id FROM man_mision_req)"},{"name":"v_nodo_zona","sql":"CREATE VIEW \"v_nodo_zona\" AS\n        WITH herbas AS (\n            SELECT s.ID AS item_id, s.Display_lang AS nombre_en, s.Display_lang_esES AS nombre\n              FROM Item i JOIN ItemSparse s ON s.ID = i.ID WHERE i.ClassID = 7 AND i.SubclassID = 9\n        ), menas AS (\n            SELECT s.ID AS item_id, s.Display_lang AS nombre_en, s.Display_lang_esES AS nombre\n              FROM Item i JOIN ItemSparse s ON s.ID = i.ID WHERE i.ClassID = 7 AND i.SubclassID = 7 AND s.Display_lang LIKE '% Ore'\n        ), base AS (\n            SELECT m.objeto_id, m.nombre_en AS objeto_en,\n                   CASE m.tipo WHEN 'herb' THEN 'hierba' ELSE 'mineral' END AS tipo\n              FROM man_nodo m\n            UNION ALL\n            SELECT o.ID, o.name,\n                   CASE WHEN o.name IN (SELECT nombre_en FROM herbas) THEN 'hierba'\n                        WHEN o.name LIKE '%Vein' OR o.name LIKE '%Deposit' THEN 'mineral'\n                        WHEN o.name LIKE '%School%' OR o.name IN ('Floating Wreckage', 'Oil Spill', 'Floating Debris') THEN 'banco de pesca'\n                   END\n              FROM questie_object o WHERE o.ID NOT IN (SELECT objeto_id FROM man_nodo)\n        ), nodos AS (\n            SELECT b.objeto_id, b.objeto_en, b.tipo, COALESCE(h.item_id, m.item_id) AS item_id\n              FROM base b\n              LEFT JOIN herbas h ON h.nombre_en = b.objeto_en\n              LEFT JOIN menas m ON m.nombre_en = replace(replace(replace(b.objeto_en, ' Mineral Vein', ' Ore'), ' Vein', ' Ore'), ' Deposit', ' Ore')\n        ), zonas_nodo AS (\n            SELECT objeto_id, zone_id, puntos, 'forever' AS origen FROM man_nodo_zona\n            UNION ALL\n            SELECT entity_id, zone_id, COUNT(*), 'questie' FROM questie_spawn\n             WHERE kind = 'object' AND entity_id NOT IN (SELECT objeto_id FROM man_nodo_zona) GROUP BY entity_id, zone_id\n        )\n        SELECT n.tipo, n.objeto_id, COALESCE(l.name, n.objeto_en) AS nombre, n.objeto_en AS nombre_en,\n               n.item_id, COALESCE(hh.nombre, mm.nombre) AS objeto_obtenido,\n               sp.zone_id AS zona_id, a.AreaName_lang_esES AS zona, sp.puntos,\n               w.veces AS veces_vistos_en_juego, h2.habilidad_min AS habilidad_minima_vista,\n               COALESCE(h2.habilidad_min, mn.habilidad_min) AS habilidad_minima,\n               CASE WHEN h2.habilidad_min IS NOT NULL THEN 'juego' WHEN mn.habilidad_min IS NOT NULL THEN 'forever' END\n                    AS origen_habilidad, sp.origen\n          FROM nodos n\n          JOIN zonas_nodo sp ON sp.objeto_id = n.objeto_id\n          LEFT JOIN man_nodo mn ON mn.objeto_id = n.objeto_id\n          LEFT JOIN AreaTable a ON a.ID = sp.zone_id\n          LEFT JOIN ext_object_l10n l ON l.object_id = n.objeto_id AND l.locale = 'esES'\n          LEFT JOIN herbas hh ON hh.item_id = n.item_id\n          LEFT JOIN menas mm ON mm.item_id = n.item_id\n          LEFT JOIN obs_wdc_nodo w ON w.entry_id = n.objeto_id\n          LEFT JOIN (SELECT entry_id, MIN(habilidad_min) AS habilidad_min FROM obs_wdc_nodo_habilidad\n                      WHERE profesion IN ('Herboristería', 'Minería', 'Herbalism', 'Mining') GROUP BY entry_id) h2\n                 ON h2.entry_id = n.objeto_id\n         WHERE n.tipo IS NOT NULL"},{"name":"v_npc","sql":"CREATE VIEW \"v_npc\" AS WITH ids AS (SELECT ID AS id FROM Creature WHERE ID IS NOT NULL UNION SELECT npc_id AS id FROM obs_wdc_npc WHERE npc_id IS NOT NULL UNION SELECT npc_id AS id FROM (SELECT npc_id, nombre FROM obs_wdb_criatura WHERE idioma = 'esES') WHERE npc_id IS NOT NULL UNION SELECT npc_id AS id FROM obs_npc_nombre WHERE npc_id IS NOT NULL UNION SELECT npc_id AS id FROM (SELECT * FROM obs_npc WHERE npc_id IS NOT NULL) WHERE npc_id IS NOT NULL UNION SELECT npc_id AS id FROM (SELECT npc_id, name FROM ext_npc_l10n WHERE locale = 'esES') WHERE npc_id IS NOT NULL UNION SELECT ID AS id FROM questie_npc WHERE ID IS NOT NULL) SELECT ids.id AS npc_id, COALESCE(s0.Name_lang_esES, s1.nombre, s2.nombre, s3.nombre, s4.nombre, s5.name, s6.name) AS nombre, COALESCE(CASE WHEN s0.Name_lang_esES IS NOT NULL THEN 'es' END, CASE WHEN s1.nombre IS NOT NULL THEN 'es' END, CASE WHEN s2.nombre IS NOT NULL THEN 'es' END, CASE WHEN s3.nombre IS NOT NULL THEN 'es' END, CASE WHEN s4.nombre IS NOT NULL THEN 'es' END, CASE WHEN s5.name IS NOT NULL THEN 'es' END, CASE WHEN s6.name IS NOT NULL THEN 'en' END) AS nombre_idioma, COALESCE(s0.Name_lang, s6.name) AS nombre_en, COALESCE(NULLIF(s1.nivel_min, 0), NULLIF(s6.minLevel, 0)) AS nivel_min, COALESCE(NULLIF(s1.nivel_max, 0), NULLIF(s6.maxLevel, 0)) AS nivel_max, COALESCE(s0.Classification, s1.clasificacion) AS clasificacion, COALESCE(s0.CreatureType, s1.tipo) AS tipo, COALESCE(s0.CreatureFamily, s1.familia) AS familia, CASE WHEN s0.ID IS NOT NULL THEN 'db2' WHEN s1.npc_id IS NOT NULL THEN 'juego' WHEN s2.npc_id IS NOT NULL THEN 'juego' WHEN s3.npc_id IS NOT NULL THEN 'juego' WHEN s4.npc_id IS NOT NULL THEN 'juego' WHEN s5.npc_id IS NOT NULL THEN 'externa' WHEN s6.ID IS NOT NULL THEN 'questie' END AS origen FROM ids LEFT JOIN (SELECT * FROM Creature) s0 ON s0.ID = ids.id LEFT JOIN (SELECT * FROM obs_wdc_npc) s1 ON s1.npc_id = ids.id LEFT JOIN (SELECT * FROM (SELECT npc_id, nombre FROM obs_wdb_criatura WHERE idioma = 'esES')) s2 ON s2.npc_id = ids.id LEFT JOIN (SELECT * FROM obs_npc_nombre) s3 ON s3.npc_id = ids.id LEFT JOIN (SELECT * FROM (SELECT * FROM obs_npc WHERE npc_id IS NOT NULL)) s4 ON s4.npc_id = ids.id LEFT JOIN (SELECT * FROM (SELECT npc_id, name FROM ext_npc_l10n WHERE locale = 'esES')) s5 ON s5.npc_id = ids.id LEFT JOIN (SELECT * FROM questie_npc) s6 ON s6.ID = ids.id"},{"name":"v_npc_pos","sql":"CREATE VIEW \"v_npc_pos\" AS\n        WITH juego AS (\n            SELECT o.npc_id AS id, u.area_id AS zona_id, ROUND(o.x * 100, 1) AS x, ROUND(o.y * 100, 1) AS y\n              FROM obs_wdc_npc_pos o JOIN ext_uimap_to_area u ON u.ui_map_id = o.map_id AND u.is_override = 0\n            UNION\n            SELECT o.npc_id, u.area_id, ROUND(o.x * 100, 1), ROUND(o.y * 100, 1)\n              FROM obs_npc o JOIN ext_uimap_to_area u ON u.ui_map_id = o.map_id AND u.is_override = 0\n             WHERE o.npc_id IS NOT NULL AND o.x IS NOT NULL),\n        zonas AS (SELECT ID, AreaName_lang FROM AreaTable WHERE ParentAreaID = 0),\n        wowhead AS (\n            SELECT w.id AS id,\n                   COALESCE((SELECT a.ID FROM AreaTable a WHERE a.ID = CAST(substr(w.mapa_ref, 2) AS INTEGER)),\n                            z.ID,\n                            (SELECT MIN(s.zone_id) FROM questie_spawn s WHERE s.kind = 'npc' AND s.entity_id = w.id\n                             HAVING COUNT(DISTINCT s.zone_id) = 1)) AS zona_id,\n                   w.x AS x, w.y AS y\n              FROM ext_wh_pos w LEFT JOIN zonas z ON z.AreaName_lang = w.zona\n             WHERE w.tipo = 'npc'),\n        questie AS (SELECT entity_id AS id, zone_id AS zona_id, x, y FROM questie_spawn WHERE kind = 'npc' AND x >= 0),\n        externa AS (SELECT npc_id AS id, zone_id AS zona_id, x, y FROM ext_npc_spawns WHERE x >= 0)\n        SELECT id AS npc_id, zona_id, x, y, 'juego' AS origen FROM juego\n        UNION ALL\n        SELECT id, zona_id, x, y, 'wowhead' FROM wowhead w\n         WHERE zona_id IS NOT NULL\n           AND NOT EXISTS (SELECT 1 FROM juego j WHERE j.id = w.id AND j.zona_id = w.zona_id)\n        UNION ALL\n        SELECT id, zona_id, x, y, 'questie' FROM questie q\n         WHERE NOT EXISTS (SELECT 1 FROM juego j WHERE j.id = q.id AND j.zona_id = q.zona_id)\n           AND NOT EXISTS (SELECT 1 FROM wowhead w WHERE w.id = q.id AND w.zona_id = q.zona_id)\n        UNION ALL\n        SELECT id, zona_id, x, y, 'externa' FROM externa e\n         WHERE NOT EXISTS (SELECT 1 FROM juego j WHERE j.id = e.id AND j.zona_id = e.zona_id)\n           AND NOT EXISTS (SELECT 1 FROM wowhead w WHERE w.id = e.id AND w.zona_id = e.zona_id)\n           AND NOT EXISTS (SELECT 1 FROM questie q WHERE q.id = e.id AND q.zona_id = e.zona_id)"},{"name":"v_npc_servicio","sql":"CREATE VIEW \"v_npc_servicio\" AS\n        WITH pos AS (\n            SELECT entity_id AS npc_id, zone_id, x, y FROM (\n                SELECT entity_id, zone_id, x, y,\n                       ROW_NUMBER() OVER (PARTITION BY entity_id ORDER BY zone_id, x, y) AS rn\n                  FROM questie_spawn WHERE kind = 'npc' AND x >= 0) WHERE rn = 1)\n        SELECT s.npc_id, COALESCE(nl.name, n.name) AS npc_nombre, n.name AS npc_nombre_en, s.servicio,\n               CASE s.servicio WHEN 'innkeeper' THEN 'posadero' WHEN 'flightmaster' THEN 'maestro de vuelo'\n                    WHEN 'battlemaster' THEN 'maestro de batalla' WHEN 'banker' THEN 'banquero'\n                    WHEN 'auctioneer' THEN 'subastador' WHEN 'mount_trainer' THEN 'instructor de monturas'\n                    WHEN 'stable_master' THEN 'maestro de establos' WHEN 'reagent' THEN 'vendedor de componentes'\n                    WHEN 'repair' THEN 'reparador' END AS servicio_es,\n               CASE s.faccion WHEN 'A' THEN 'Alianza' WHEN 'H' THEN 'Horda' WHEN 'both' THEN 'Ambas' END AS faccion,\n               s.taxi_node_id, tn.Name_lang_esES AS nodo_vuelo, s.battleground_id,\n               p.zone_id AS zona_id, ar.AreaName_lang_esES AS zona, p.x, p.y, 'forever' AS origen\n          FROM man_npc_servicio s\n          LEFT JOIN questie_npc n ON n.ID = s.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = s.npc_id AND nl.locale = 'esES'\n          LEFT JOIN TaxiNodes tn ON tn.ID = s.taxi_node_id\n          LEFT JOIN pos p ON p.npc_id = s.npc_id\n          LEFT JOIN AreaTable ar ON ar.ID = p.zone_id"},{"name":"v_objeto","sql":"CREATE VIEW \"v_objeto\" AS WITH ids AS (SELECT ID AS id FROM ItemSparse WHERE ID IS NOT NULL UNION SELECT item_id AS id FROM obs_objeto WHERE item_id IS NOT NULL UNION SELECT ID AS id FROM questie_item WHERE ID IS NOT NULL) SELECT ids.id AS item_id, COALESCE(s0.Display_lang_esES, s1.nombre, s2.name) AS nombre, s0.Display_lang AS nombre_en, COALESCE(NULLIF(s0.ItemLevel, 0), NULLIF(s1.nivel_objeto, 0), NULLIF(s2.itemLevel, 0)) AS nivel_objeto, COALESCE(NULLIF(s0.RequiredLevel, 0), NULLIF(s1.nivel_requerido, 0), NULLIF(s2.requiredLevel, 0)) AS nivel_requerido, CASE WHEN s0.ID IS NOT NULL THEN 'db2' WHEN s1.item_id IS NOT NULL THEN 'juego' WHEN s2.ID IS NOT NULL THEN 'questie' END AS origen FROM ids LEFT JOIN (SELECT * FROM ItemSparse) s0 ON s0.ID = ids.id LEFT JOIN (SELECT * FROM obs_objeto) s1 ON s1.item_id = ids.id LEFT JOIN (SELECT * FROM questie_item) s2 ON s2.ID = ids.id"},{"name":"v_objeto_fuente","sql":"CREATE VIEW \"v_objeto_fuente\" AS\n        WITH pos AS (\n            SELECT entity_id AS npc_id, zone_id, x, y FROM (\n                SELECT entity_id, zone_id, x, y,\n                       ROW_NUMBER() OVER (PARTITION BY entity_id ORDER BY zone_id, x, y) AS rn\n                  FROM questie_spawn WHERE kind = 'npc' AND x >= 0) WHERE rn = 1\n        ), fuentes AS (\n            SELECT item_id, 'vendedor' AS tipo, npc_id, precio, NULL AS quest_id, 'juego' AS origen\n              FROM obs_wdc_vendedor\n            UNION ALL\n            SELECT c.VendorItemID, 'vendedor', c.CreatureID, NULL, NULL, 'db2' FROM collectablesourcevendorsparse c\n             WHERE c.CreatureID > 0\n               AND NOT EXISTS (SELECT 1 FROM obs_wdc_vendedor v WHERE v.item_id = c.VendorItemID AND v.npc_id = c.CreatureID)\n            UNION ALL\n            SELECT mv.item_id, 'vendedor', mv.npc_id, MIN(mv.precio), NULL, 'forever' FROM man_vendedor_objeto mv\n             WHERE NOT EXISTS (SELECT 1 FROM obs_wdc_vendedor v WHERE v.item_id = mv.item_id AND v.npc_id = mv.npc_id)\n               AND NOT EXISTS (SELECT 1 FROM collectablesourcevendorsparse c WHERE c.VendorItemID = mv.item_id\n                                                                              AND c.CreatureID = mv.npc_id)\n             GROUP BY mv.item_id, mv.npc_id\n            UNION ALL\n            SELECT d.item_id, 'vendedor', d.source_id, NULL, NULL, 'questie' FROM questie_item_drop d\n             WHERE d.source = 'vendor'\n               AND NOT EXISTS (SELECT 1 FROM man_vendedor_objeto mv WHERE mv.item_id = d.item_id AND mv.npc_id = d.source_id)\n               AND NOT EXISTS (SELECT 1 FROM obs_wdc_vendedor v WHERE v.item_id = d.item_id AND v.npc_id = d.source_id)\n               AND NOT EXISTS (SELECT 1 FROM collectablesourcevendorsparse c WHERE c.VendorItemID = d.item_id\n                                                                              AND c.CreatureID = d.source_id)\n            UNION ALL\n            SELECT m.item_id, 'vendedor', n.id, NULL, NULL, 'forever'\n              FROM man_receta_libro m\n              JOIN man_receta_libro_fuente mf ON mf.item_id = m.item_id\n              JOIN (SELECT name, MIN(ID) AS id FROM questie_npc GROUP BY name HAVING COUNT(*) = 1) n ON n.name = mf.nombre\n             WHERE m.fuentes LIKE '%Vendor%'\n               AND NOT EXISTS (SELECT 1 FROM man_vendedor_objeto mv WHERE mv.item_id = m.item_id)\n               AND NOT EXISTS (SELECT 1 FROM obs_wdc_vendedor v WHERE v.item_id = m.item_id)\n               AND NOT EXISTS (SELECT 1 FROM collectablesourcevendorsparse c WHERE c.VendorItemID = m.item_id)\n            UNION ALL\n            SELECT r.item_id, CASE r.tipo WHEN 'vendor' THEN 'vendedor' WHEN 'drop' THEN 'botin'\n                                          WHEN 'quest' THEN 'mision' END,\n                   r.npc_id, r.precio, r.quest_id, 'forever'\n              FROM man_receta_fuente r\n             WHERE r.tipo IN ('drop', 'quest')\n                OR (r.tipo = 'vendor' AND NOT EXISTS (SELECT 1 FROM man_vendedor_objeto mv WHERE mv.item_id = r.item_id AND mv.npc_id = r.npc_id)\n                AND NOT EXISTS (SELECT 1 FROM obs_wdc_vendedor v WHERE v.item_id = r.item_id AND v.npc_id = r.npc_id)\n                AND NOT EXISTS (SELECT 1 FROM collectablesourcevendorsparse c WHERE c.VendorItemID = r.item_id AND c.CreatureID = r.npc_id))\n            UNION ALL\n            SELECT item_id, 'botin', source_id, NULL, NULL, 'questie' FROM questie_item_drop WHERE source = 'npc'\n            UNION ALL\n            SELECT item_id, 'mision', NULL, NULL, quest_id, 'questie' FROM ext_item_quest_rewards\n        )\n        SELECT f.item_id, f.tipo, f.npc_id, COALESCE(nl.name, n.name) AS npc_nombre, p.zone_id AS zona_id,\n               ar.AreaName_lang_esES AS zona, p.x, p.y,\n               CASE n.friendlyToFaction WHEN 'A' THEN 'Alianza' WHEN 'H' THEN 'Horda' WHEN 'AH' THEN 'Ambas' END AS faccion,\n               COALESCE(f.precio, s.BuyPrice) AS precio, f.quest_id, f.origen\n          FROM fuentes f\n          LEFT JOIN questie_npc n ON n.ID = f.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = f.npc_id AND nl.locale = 'esES'\n          LEFT JOIN pos p ON p.npc_id = f.npc_id\n          LEFT JOIN AreaTable ar ON ar.ID = p.zone_id\n          LEFT JOIN ItemSparse s ON s.ID = f.item_id"},{"name":"v_objeto_fuente_contenedor","sql":"CREATE VIEW \"v_objeto_fuente_contenedor\" AS\n        SELECT r.item_id, COALESCE(s.Display_lang_esES, s.Display_lang) AS objeto, r.objeto_id, o.name AS contenedor_en,\n               'forever' AS origen\n          FROM man_receta_fuente r\n          LEFT JOIN ItemSparse s ON s.ID = r.item_id\n          LEFT JOIN questie_object o ON o.ID = r.objeto_id\n         WHERE r.tipo = 'object'"},{"name":"v_objeto_pos","sql":"CREATE VIEW \"v_objeto_pos\" AS\n        WITH juego AS (SELECT NULL AS id, NULL AS zona_id, NULL AS x, NULL AS y WHERE 0),\n        zonas AS (SELECT ID, AreaName_lang FROM AreaTable WHERE ParentAreaID = 0),\n        wowhead AS (\n            SELECT w.id AS id,\n                   COALESCE((SELECT a.ID FROM AreaTable a WHERE a.ID = CAST(substr(w.mapa_ref, 2) AS INTEGER)),\n                            z.ID,\n                            (SELECT MIN(s.zone_id) FROM questie_spawn s WHERE s.kind = 'object' AND s.entity_id = w.id\n                             HAVING COUNT(DISTINCT s.zone_id) = 1)) AS zona_id,\n                   w.x AS x, w.y AS y\n              FROM ext_wh_pos w LEFT JOIN zonas z ON z.AreaName_lang = w.zona\n             WHERE w.tipo = 'object'),\n        questie AS (SELECT entity_id AS id, zone_id AS zona_id, x, y FROM questie_spawn WHERE kind = 'object' AND x >= 0),\n        externa AS (SELECT object_id AS id, zone_id AS zona_id, x, y FROM ext_object_spawns WHERE x >= 0)\n        SELECT id AS objeto_id, zona_id, x, y, 'juego' AS origen FROM juego\n        UNION ALL\n        SELECT id, zona_id, x, y, 'wowhead' FROM wowhead w\n         WHERE zona_id IS NOT NULL\n           AND NOT EXISTS (SELECT 1 FROM juego j WHERE j.id = w.id AND j.zona_id = w.zona_id)\n        UNION ALL\n        SELECT id, zona_id, x, y, 'questie' FROM questie q\n         WHERE NOT EXISTS (SELECT 1 FROM juego j WHERE j.id = q.id AND j.zona_id = q.zona_id)\n           AND NOT EXISTS (SELECT 1 FROM wowhead w WHERE w.id = q.id AND w.zona_id = q.zona_id)\n        UNION ALL\n        SELECT id, zona_id, x, y, 'externa' FROM externa e\n         WHERE NOT EXISTS (SELECT 1 FROM juego j WHERE j.id = e.id AND j.zona_id = e.zona_id)\n           AND NOT EXISTS (SELECT 1 FROM wowhead w WHERE w.id = e.id AND w.zona_id = e.zona_id)\n           AND NOT EXISTS (SELECT 1 FROM questie q WHERE q.id = e.id AND q.zona_id = e.zona_id)"},{"name":"v_pesca_zona","sql":"CREATE VIEW \"v_pesca_zona\" AS\n        WITH zonas AS (\n            SELECT ui_map_id FROM ff_pesca_zona UNION SELECT map_id FROM obs_wdc_pesca\n            UNION SELECT map_id FROM ff_pesca_habilidad\n        ), peces AS (\n            SELECT map_id, item_id, SUM(veces) AS veces FROM (\n                SELECT map_id, item_id, veces FROM ff_pesca_objeto\n                UNION ALL SELECT map_id, item_id, veces FROM obs_wdc_pesca_objeto) GROUP BY map_id, item_id\n        ), top AS (\n            SELECT map_id, group_concat(nombre, ', ') AS peces FROM (\n                SELECT p.map_id, COALESCE(s.Display_lang_esES, s.Display_lang) AS nombre,\n                       ROW_NUMBER() OVER (PARTITION BY p.map_id ORDER BY p.veces DESC) AS rn\n                  FROM peces p LEFT JOIN ItemSparse s ON s.ID = p.item_id) WHERE rn <= 5 GROUP BY map_id\n        ), escapes AS (\n            SELECT map_id, SUM(lanzamientos) AS lanzamientos, SUM(capturas) AS capturas, SUM(escapes) AS escapes,\n                   MAX(CASE WHEN escapes > 0 THEN habilidad END) AS habilidad_con_escapes,\n                   MIN(CASE WHEN escapes = 0 AND lanzamientos >= 3 THEN habilidad END) AS habilidad_sin_escapes\n              FROM ff_pesca_habilidad GROUP BY map_id\n        ), fallos AS (\n            SELECT map_id, MAX(habilidad_max) AS habilidad FROM obs_wdc_pesca_error\n             WHERE mensaje LIKE '%not high enough%' OR mensaje LIKE '%skill%' OR mensaje LIKE '%suficiente%'\n                OR mensaje LIKE '%insuficiente%' OR mensaje LIKE '%bastante%' GROUP BY map_id\n        )\n        SELECT z.ui_map_id, ar.area_id AS zone_id, u.Name_lang_esES AS zona, u.Name_lang AS zona_en,\n               CASE WHEN fl.habilidad IS NOT NULL AND (f.habilidad_min IS NULL OR f.habilidad_min <= fl.habilidad)\n                         THEN fl.habilidad + 1\n                    WHEN o.habilidad_min IS NOT NULL AND (f.habilidad_min IS NULL OR o.habilidad_min < f.habilidad_min)\n                         THEN o.habilidad_min\n                    ELSE f.habilidad_min END AS habilidad_minima_para_pescar,\n               tp.peces AS peces_principales,\n               (SELECT group_concat(COALESCE(s.Display_lang_esES, s.Display_lang), ', ')\n                  FROM man_pesca_zona_pez m JOIN ItemSparse s ON s.ID = m.item_id\n                 WHERE m.zone_id = ar.area_id) AS peces_posibles,\n               o.capturas AS capturas_vistas,\n               fl.habilidad AS habilidad_con_fallo, o.habilidad_min AS habilidad_con_exito,\n               es.lanzamientos AS lanzamientos_vistos, es.escapes AS escapes_vistos,\n               es.habilidad_con_escapes - 94 AS cota_inferior_por_escapes,\n               MAX(es.habilidad_sin_escapes - 95, 1) AS cota_superior_por_escapes,\n               CASE WHEN fl.habilidad IS NOT NULL AND o.habilidad_min IS NOT NULL AND o.habilidad_min - fl.habilidad <= 5\n                    THEN 1\n                    WHEN es.habilidad_con_escapes IS NOT NULL AND es.habilidad_sin_escapes IS NOT NULL\n                         AND f.habilidad_min BETWEEN es.habilidad_con_escapes - 94 AND MAX(es.habilidad_sin_escapes - 95, 1)\n                    THEN 1 ELSE 0 END AS verificada,\n               CASE WHEN fl.habilidad IS NOT NULL AND (f.habilidad_min IS NULL OR f.habilidad_min <= fl.habilidad) THEN 'juego'\n                    WHEN o.habilidad_min IS NOT NULL AND (f.habilidad_min IS NULL OR o.habilidad_min < f.habilidad_min) THEN 'juego'\n                    ELSE 'fishforever' END AS origen\n          FROM zonas z\n          LEFT JOIN ff_pesca_zona f ON f.ui_map_id = z.ui_map_id\n          LEFT JOIN obs_wdc_pesca o ON o.map_id = z.ui_map_id\n          LEFT JOIN fallos fl ON fl.map_id = z.ui_map_id\n          LEFT JOIN escapes es ON es.map_id = z.ui_map_id\n          LEFT JOIN UiMap u ON u.ID = z.ui_map_id\n          LEFT JOIN ext_uimap_to_area ar ON ar.ui_map_id = z.ui_map_id AND ar.is_override = 0\n          LEFT JOIN top tp ON tp.map_id = z.ui_map_id"},{"name":"v_pesca_zona_pez","sql":"CREATE VIEW \"v_pesca_zona_pez\" AS\n        SELECT m.zone_id, a.AreaName_lang_esES AS zona, a.AreaName_lang AS zona_en, m.item_id,\n               s.Display_lang_esES AS pez, s.Display_lang AS pez_en, 'forever' AS origen\n          FROM man_pesca_zona_pez m\n          LEFT JOIN AreaTable a ON a.ID = m.zone_id\n          LEFT JOIN ItemSparse s ON s.ID = m.item_id"},{"name":"v_profesion","sql":"CREATE VIEW \"v_profesion\" AS\n        SELECT sl.ID AS profesion_id, sl.DisplayName_lang_esES AS nombre, sl.DisplayName_lang AS nombre_en,\n               CASE WHEN sl.ID IN (129, 185, 356) THEN 'secundaria' ELSE 'primaria' END AS tipo, 'db2' AS origen\n          FROM SkillLine sl WHERE sl.ID IN (164, 165, 171, 182, 186, 197, 202, 333, 393, 129, 185, 356)"},{"name":"v_profesion_instructor","sql":"CREATE VIEW \"v_profesion_instructor\" AS\n        WITH prof(profesion_id, en, es) AS (VALUES\n            (164, 'Blacksmith', 'Herrer'), (165, 'Leatherwork', 'Peleter'), (171, 'Alchemy', 'Alquimia'),\n            (182, 'Herbalism', 'Botánica'), (186, 'Mining', 'Minería'), (197, 'Tailor', 'Costura'),\n            (202, 'Engineer', 'Ingenier'), (333, 'Enchant', 'Encantamiento'), (393, 'Skinning', 'Desuello'),\n            (129, 'First Aid', 'Primeros auxilios'), (185, 'Cooking', 'Cocina'), (356, 'Fishing', 'Pesca')\n        ), subs AS (\n            SELECT npc_id, MAX(CASE WHEN locale = 'enUS' THEN sub_name END) AS sub_en,\n                   MAX(CASE WHEN locale = 'esES' THEN replace(sub_name, char(160), ' ') END) AS sub_es\n              FROM ext_npc_l10n GROUP BY npc_id\n        ), por_nombre AS (\n            SELECT s.npc_id, p.profesion_id, s.sub_en, s.sub_es, 'questie' AS origen\n              FROM subs s JOIN prof p\n                ON (s.sub_en LIKE '%Trainer%' AND s.sub_en LIKE '%' || p.en || '%')\n                OR (s.sub_es LIKE '%nstructor%' AND s.sub_es LIKE '%' || p.es || '%')\n        ), observados AS (\n            SELECT i.npc_id, COALESCE(NULLIF(sl.ParentSkillLineID, 0), sl.ID) AS profesion_id, NULL AS sub_en, NULL AS sub_es,\n                   'juego' AS origen\n              FROM obs_instructor_servicio i\n              JOIN SkillLineAbility a ON a.Spell = i.spell_id JOIN SkillLine sl ON sl.ID = a.SkillLine\n             WHERE COALESCE(NULLIF(sl.ParentSkillLineID, 0), sl.ID) IN (SELECT profesion_id FROM prof)\n             GROUP BY i.npc_id, 2\n        ), manual AS (\n            SELECT npc_id, profesion_id, NULL AS sub_en, NULL AS sub_es, 'forever' AS origen FROM man_instructor\n            UNION\n            SELECT npc_id, profesion_id, NULL, NULL, 'forever' FROM man_entrenador\n             WHERE tipo = 'profession' AND profesion_id IS NOT NULL\n               AND NOT EXISTS (SELECT 1 FROM man_instructor i WHERE i.npc_id = man_entrenador.npc_id\n                                                                  AND i.profesion_id = man_entrenador.profesion_id)\n        ), conocidos AS (\n            SELECT * FROM observados\n            UNION ALL\n            SELECT * FROM manual m WHERE NOT EXISTS (SELECT 1 FROM observados o WHERE o.npc_id = m.npc_id\n                                                     AND o.profesion_id = m.profesion_id)\n        ), todos AS (\n            SELECT * FROM conocidos\n            UNION ALL\n            SELECT * FROM por_nombre n WHERE NOT EXISTS (SELECT 1 FROM conocidos o WHERE o.npc_id = n.npc_id\n                                                         AND o.profesion_id = n.profesion_id)\n        ), pos AS (\n            SELECT entity_id AS npc_id, zone_id, x, y FROM (\n                SELECT entity_id, zone_id, x, y,\n                       ROW_NUMBER() OVER (PARTITION BY entity_id ORDER BY zone_id, x, y) AS rn\n                  FROM questie_spawn WHERE kind = 'npc' AND x >= 0) WHERE rn = 1\n        ), rangos AS (\n            SELECT i.npc_id, MAX(r.habilidad_max) AS habilidad_max, MAX(r.rango) AS rango\n              FROM obs_instructor_servicio i JOIN v_profesion_rango r ON r.spell_id = i.spell_id GROUP BY i.npc_id\n        )\n        SELECT t.npc_id, COALESCE(nl.name, n.name, mi.nombre_en) AS nombre, COALESCE(n.name, mi.nombre_en) AS nombre_en, t.profesion_id,\n               COALESCE(rg.rango, CASE mi.rango_max WHEN 'Apprentice' THEN 'Aprendiz' WHEN 'Journeyman' THEN 'Oficial'\n                                                    WHEN 'Expert' THEN 'Experto' WHEN 'Artisan' THEN 'Artesano' END)\n                    AS rango_maximo_que_ensena,\n               COALESCE(rg.habilidad_max, CASE mi.rango_max WHEN 'Apprentice' THEN 75 WHEN 'Journeyman' THEN 150\n                                                           WHEN 'Expert' THEN 225 WHEN 'Artisan' THEN 300 END)\n                    AS habilidad_maxima_que_ensena,\n               (SELECT group_concat(DISTINCT r.rango || ': ' || r.coste) FROM man_instructor_rango r\n                 WHERE r.npc_id = t.npc_id AND r.profesion_id = t.profesion_id) AS costes_por_rango,\n               CASE WHEN t.sub_en LIKE 'Junior%' THEN 1 ELSE 0 END AS es_junior,\n               CASE n.friendlyToFaction WHEN 'A' THEN 'Alianza' WHEN 'H' THEN 'Horda' WHEN 'AH' THEN 'Ambas' END AS faccion,\n               p.zone_id, ar.AreaName_lang_esES AS zona, p.x, p.y, t.origen\n          FROM todos t\n          LEFT JOIN questie_npc n ON n.ID = t.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = t.npc_id AND nl.locale = 'esES'\n          LEFT JOIN pos p ON p.npc_id = t.npc_id\n          LEFT JOIN AreaTable ar ON ar.ID = p.zone_id\n          LEFT JOIN rangos rg ON rg.npc_id = t.npc_id\n          LEFT JOIN man_instructor mi ON mi.npc_id = t.npc_id AND mi.profesion_id = t.profesion_id"},{"name":"v_profesion_libro","sql":"CREATE VIEW \"v_profesion_libro\" AS\n        WITH libros AS (\n            SELECT item_id, 'rango' AS tipo_libro, profesion_id, rango, spell_id AS receta_id, NULL AS receta,\n                   NULL AS habilidad_requerida, conjunto, nivel_requerido AS nivel_aprendizaje\n              FROM v_profesion_rango WHERE item_id IS NOT NULL\n            UNION ALL\n            SELECT objeto_receta_id, 'receta', profesion_id, NULL, receta_id, nombre, habilidad_requerida, 'clasico', NULL\n              FROM v_receta WHERE objeto_receta_id IS NOT NULL\n        )\n        SELECT l.item_id,\n               COALESCE(s.Display_lang_esES, oi.nombre, il.name, qi.name) AS nombre,\n               COALESCE(s.Display_lang, qi.name) AS nombre_en,\n               l.tipo_libro, l.profesion_id, l.rango, l.receta_id, l.receta,\n               CASE WHEN l.tipo_libro = 'receta' THEN COALESCE(NULLIF(s.RequiredSkillRank, 0), m.habilidad, l.habilidad_requerida)\n                    ELSE l.habilidad_requerida END AS habilidad_requerida, l.conjunto,\n               m.fuentes AS tipos_fuente_forever,\n               (SELECT group_concat(nombre, ', ') FROM man_receta_libro_fuente mf WHERE mf.item_id = l.item_id) AS nombres_fuente_forever,\n               COALESCE(NULLIF(s.RequiredLevel, 0), oi.nivel_requerido, NULLIF(m.nivel_requerido, 0), l.nivel_aprendizaje, qi.requiredLevel) AS nivel_requerido,\n               COALESCE(NULLIF(s.ItemLevel, 0), oi.nivel_objeto, qi.itemLevel) AS nivel_objeto,\n               f.tipo AS fuente, f.npc_id, f.npc_nombre, f.zona_id, f.zona, f.x, f.y, f.faccion, f.precio,\n               f.quest_id, COALESCE(f.origen, 'db2') AS origen,\n               CASE WHEN s.ID IS NOT NULL THEN 'db2' WHEN oi.item_id IS NOT NULL THEN 'juego'\n                    WHEN il.item_id IS NOT NULL OR qi.ID IS NOT NULL THEN 'questie' ELSE NULL END AS origen_nombre\n          FROM libros l\n          LEFT JOIN ItemSparse s ON s.ID = l.item_id\n          LEFT JOIN obs_wdc_objeto_info oi ON oi.item_id = l.item_id\n          LEFT JOIN man_receta_libro m ON m.item_id = l.item_id\n          LEFT JOIN ext_item_l10n il ON il.item_id = l.item_id AND il.locale = 'esES'\n          LEFT JOIN questie_item qi ON qi.ID = l.item_id\n          LEFT JOIN v_objeto_fuente f ON f.item_id = l.item_id"},{"name":"v_profesion_rango","sql":"CREATE VIEW \"v_profesion_rango\" AS\n        WITH escalones AS (\n            SELECT DISTINCT a.Spell AS spell_id, COALESCE(NULLIF(sl.ParentSkillLineID, 0), sl.ID) AS profesion_id,\n                   CASE WHEN a.Spell >= 1000000 THEN 'forever' ELSE 'clasico' END AS conjunto,\n                   sp.NameSubtext_lang_esES AS rango, sp.NameSubtext_lang AS rango_en,\n                   CAST(e.EffectBasePointsF AS INTEGER) AS escalon\n              FROM SkillLineAbility a\n              JOIN SkillLine sl ON sl.ID = a.SkillLine\n              JOIN Spell sp ON sp.ID = a.Spell\n                            AND sp.NameSubtext_lang_esES IN ('Aprendiz', 'Oficial', 'Experto', 'Artesano', 'Maestro')\n              JOIN SpellEffect e ON e.SpellID = a.Spell AND e.Effect = 118\n        ), libros AS (\n            SELECT se.EffectTriggerSpell AS spell_id, MIN(x.ItemID) AS item_id\n              FROM ItemEffect ie JOIN itemxitemeffect x ON x.ItemEffectID = ie.ID\n              JOIN SpellEffect se ON se.SpellID = ie.SpellID AND se.Effect = 36\n             GROUP BY se.EffectTriggerSpell\n        )\n        SELECT profesion_id, rango, rango_en, conjunto, habilidad_min, habilidad_max, nivel_requerido, spell_id,\n               como_se_aprende, item_id, item_nombre, quest_id, origen, spell_id_alternativo FROM (\n            SELECT z.profesion_id, z.rango, z.rango_en, z.conjunto,\n                   CASE WHEN z.escalon = 1 THEN 1 ELSE (z.escalon - 1) * 75 END AS habilidad_min, z.escalon * 75 AS habilidad_max,\n                   COALESCE(o.nivel, NULLIF(s.RequiredLevel, 0)) AS nivel_requerido, z.spell_id,\n                   CASE WHEN l.item_id IS NULL THEN 'instructor'\n                        WHEN q.quest_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM questie_item_drop d\n                                                                     WHERE d.item_id = l.item_id AND d.source = 'vendor') THEN 'mision'\n                        ELSE 'objeto' END AS como_se_aprende,\n                   l.item_id, COALESCE(s.Display_lang_esES, il.name, qi.name) AS item_nombre, q.quest_id,\n                   CASE WHEN o.nivel IS NOT NULL OR o.spell_id IS NOT NULL THEN 'juego' ELSE 'db2' END AS origen,\n                   (SELECT MIN(z2.spell_id) FROM escalones z2 WHERE z2.profesion_id = z.profesion_id AND z2.rango = z.rango\n                       AND z2.spell_id <> z.spell_id) AS spell_id_alternativo,\n                   ROW_NUMBER() OVER (PARTITION BY z.profesion_id, z.rango\n                                      ORDER BY (l.item_id IS NULL), (o.spell_id IS NULL), z.spell_id) AS rn\n              FROM escalones z\n              LEFT JOIN libros l ON l.spell_id = z.spell_id\n              LEFT JOIN ItemSparse s ON s.ID = l.item_id\n              LEFT JOIN ext_item_l10n il ON il.item_id = l.item_id AND il.locale = 'esES'\n              LEFT JOIN questie_item qi ON qi.ID = l.item_id\n              LEFT JOIN (SELECT item_id, MIN(quest_id) AS quest_id FROM ext_item_quest_rewards GROUP BY item_id) q\n                     ON q.item_id = l.item_id\n              LEFT JOIN (SELECT spell_id, MIN(nivel_req) AS nivel FROM obs_instructor_servicio WHERE spell_id IS NOT NULL\n                          GROUP BY spell_id) o ON o.spell_id = z.spell_id\n        ) WHERE rn = 1"},{"name":"v_receta","sql":"CREATE VIEW \"v_receta\" AS\n        SELECT COALESCE(NULLIF(sl.ParentSkillLineID, 0), sl.ID) AS profesion_id, sl.DisplayName_lang_esES AS profesion,\n               sl.DisplayName_lang AS profesion_en, a.Spell AS receta_id, a.Spell AS spell_id,\n               n.Name_lang_esES AS nombre, n.Name_lang AS nombre_en,\n               a.MinSkillLineRank AS habilidad_requerida, a.MinSkillLineRank AS habilidad_naranja,\n               a.TrivialSkillLineRankLow AS habilidad_amarillo,\n               (a.TrivialSkillLineRankLow + a.TrivialSkillLineRankHigh) / 2 AS habilidad_verde,\n               a.TrivialSkillLineRankHigh AS habilidad_gris,\n               (SELECT group_concat(r.cantidad || 'x ' || COALESCE(r.objeto, r.objeto_en, CAST(r.item_id AS TEXT)), '; ')\n                  FROM v_receta_reactivo r WHERE r.receta_id = a.Spell) AS reactivos,\n               CASE WHEN ens.item_id IS NOT NULL THEN 'objeto' ELSE 'instructor' END AS como_se_aprende,\n               ens.item_id AS objeto_receta_id, sr.Display_lang_esES AS objeto_receta,\n               e.item_id AS objeto_id, s.Display_lang_esES AS objeto, s.Display_lang AS objeto_en,\n               s.ItemLevel AS nivel_objeto, s.RequiredLevel AS nivel_requerido, s.OverallQualityID AS calidad,\n               EXISTS (SELECT 1 FROM obs_wdc_receta o WHERE o.receta = CAST(a.Spell AS TEXT)) AS vista_en_juego,\n               'db2' AS origen\n          FROM SkillLineAbility a\n          JOIN SkillLine sl ON sl.ID = a.SkillLine\n           AND a.SkillLine IN (164, 165, 171, 182, 186, 197, 202, 333, 393, 129, 185, 356, 40, 633, 2939, 2942, 2943, 2988)\n          LEFT JOIN SpellName n ON n.ID = a.Spell\n          LEFT JOIN (SELECT SpellID, MIN(EffectItemType) AS item_id FROM SpellEffect\n                      WHERE Effect = 24 AND EffectItemType > 0 GROUP BY SpellID) e ON e.SpellID = a.Spell\n          LEFT JOIN ItemSparse s ON s.ID = e.item_id\n          LEFT JOIN (SELECT spell_id, MIN(item_id) AS item_id FROM (\n                        SELECT se.EffectTriggerSpell AS spell_id, x.ItemID AS item_id\n                          FROM ItemEffect ie JOIN itemxitemeffect x ON x.ItemEffectID = ie.ID\n                          JOIN SpellEffect se ON se.SpellID = ie.SpellID AND se.Effect = 36 AND se.EffectTriggerSpell > 0\n                        UNION ALL\n                        SELECT ie.SpellID, x.ItemID FROM ItemEffect ie JOIN itemxitemeffect x ON x.ItemEffectID = ie.ID\n                         WHERE ie.TriggerType = 6) GROUP BY spell_id) ens ON ens.spell_id = a.Spell\n          LEFT JOIN ItemSparse sr ON sr.ID = ens.item_id\n         WHERE a.Spell IS NOT NULL"},{"name":"v_receta_reactivo","sql":"CREATE VIEW \"v_receta_reactivo\" AS\n        SELECT r.SpellID AS receta_id, CAST(i.value AS INTEGER) AS item_id, CAST(c.value AS INTEGER) AS cantidad,\n               s.Display_lang_esES AS objeto, s.Display_lang AS objeto_en\n          FROM SpellReagents r\n          JOIN json_each(r.Reagent) i\n          JOIN json_each(r.ReagentCount) c ON c.key = i.key\n          LEFT JOIN ItemSparse s ON s.ID = CAST(i.value AS INTEGER)\n         WHERE CAST(i.value AS INTEGER) > 0"},{"name":"v_ruta","sql":"CREATE VIEW \"v_ruta\" AS\n        WITH puntos AS (\n            SELECT PathID, NodeIndex, ContinentID,\n                   json_extract(Loc, '$[0]') AS x, json_extract(Loc, '$[1]') AS y, json_extract(Loc, '$[2]') AS z\n              FROM TaxiPathNode\n        ), tramos AS (\n            SELECT PathID, ContinentID,\n                   sqrt(power(x - LAG(x) OVER w, 2) + power(y - LAG(y) OVER w, 2) + power(z - LAG(z) OVER w, 2)) AS d\n              FROM puntos WINDOW w AS (PARTITION BY PathID ORDER BY NodeIndex)\n        ), extremos AS (\n            SELECT DISTINCT PathID,\n                   FIRST_VALUE(x) OVER w AS x0, FIRST_VALUE(y) OVER w AS y0,\n                   LAST_VALUE(x) OVER w AS x1, LAST_VALUE(y) OVER w AS y1\n              FROM puntos\n            WINDOW w AS (PARTITION BY PathID ORDER BY NodeIndex ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)\n        ), medidas AS (\n            SELECT PathID, MIN(ContinentID) AS continente, COUNT(*) AS puntos, ROUND(SUM(COALESCE(d, 0)), 1) AS longitud FROM tramos GROUP BY PathID\n        ), dist AS (\n            SELECT e.PathID, t.Name_lang,\n                   power(json_extract(t.Pos, '$[0]') - e.x0, 2) + power(json_extract(t.Pos, '$[1]') - e.y0, 2) AS d0,\n                   power(json_extract(t.Pos, '$[0]') - e.x1, 2) + power(json_extract(t.Pos, '$[1]') - e.y1, 2) AS d1\n              FROM extremos e JOIN medidas m ON m.PathID = e.PathID JOIN TaxiNodes t ON t.ContinentID = m.continente\n        ), ci AS (\n            SELECT PathID, Name_lang FROM (SELECT PathID, Name_lang, ROW_NUMBER() OVER (PARTITION BY PathID ORDER BY d0) AS rn FROM dist) WHERE rn = 1\n        ), cf AS (\n            SELECT PathID, Name_lang FROM (SELECT PathID, Name_lang, ROW_NUMBER() OVER (PARTITION BY PathID ORDER BY d1) AS rn FROM dist) WHERE rn = 1\n        )\n        SELECT p.ID AS ruta_id,\n               CASE WHEN a.ID IS NULL AND oi.ruta_id IS NOT NULL THEN 'transporte (barco, zepelín, transbordador)'\n                    WHEN a.ID IS NULL THEN 'trayecto sin nodos (transporte o script)'\n                    WHEN a.Name_lang LIKE 'Quest Path%' THEN 'misión'\n                    WHEN a.ContinentID = 30 THEN 'campo de batalla'\n                    WHEN a.Flags = 1027 THEN 'torre'\n                    WHEN p.Cost > 0 THEN 'vuelo'\n                    WHEN a.Name_lang LIKE 'Nighthaven%' OR b.Name_lang LIKE 'Nighthaven%' THEN 'vuelo gratuito'\n                    ELSE 'transporte (barco, zepelín, transbordador)' END AS tipo,\n               p.FromTaxiNode AS nodo_origen, COALESCE(a.Name_lang, oi.subzona_ini || ', ' || oi.zona_ini) AS origen, p.ToTaxiNode AS nodo_destino, COALESCE(b.Name_lang, oi.subzona_fin || ', ' || oi.zona_fin) AS destino,\n               COALESCE(a.ContinentID, m.continente) AS continente_origen, COALESCE(b.ContinentID, m.continente) AS continente_destino,\n               CASE a.Flags WHEN 1025 THEN 'Alianza' WHEN 1026 THEN 'Horda' ELSE NULL END AS faccion,\n               p.Cost AS coste, m.puntos, m.longitud,\n               ROUND(e.x0, 1) AS inicio_x, ROUND(e.y0, 1) AS inicio_y, ROUND(e.x1, 1) AS fin_x, ROUND(e.y1, 1) AS fin_y,\n               ci.Name_lang AS cerca_del_inicio, cf.Name_lang AS cerca_del_fin,\n               oi.zona_ini || ' -> ' || oi.zona_fin AS visto_en_juego, oi.viajes AS viajes_vistos\n          FROM TaxiPath p\n          LEFT JOIN TaxiNodes a ON a.ID = p.FromTaxiNode\n          LEFT JOIN TaxiNodes b ON b.ID = p.ToTaxiNode\n          LEFT JOIN medidas m ON m.PathID = p.ID\n          LEFT JOIN extremos e ON e.PathID = p.ID\n          LEFT JOIN ci ON ci.PathID = p.ID\n          LEFT JOIN cf ON cf.PathID = p.ID\n          LEFT JOIN obs_ruta_identificada oi ON oi.ruta_id = p.ID"},{"name":"v_talentos","sql":"CREATE VIEW \"v_talentos\" AS \n        SELECT tn.TraitTreeID AS TreeID, tn.ID AS NodeID, tn.PosX AS PosX, tn.PosY AS PosY,\n               tne.MaxRanks AS MaxRanks, td.SpellID AS SpellID,\n               sn.Name_lang AS Name_enUS, sn.Name_lang_esES AS Name_esES\n        FROM TraitNode tn\n        JOIN TraitNodeXTraitNodeEntry x ON x.TraitNodeID = tn.ID\n        JOIN TraitNodeEntry tne ON tne.ID = x.TraitNodeEntryID\n        JOIN TraitDefinition td ON td.ID = tne.TraitDefinitionID\n        LEFT JOIN SpellName sn ON sn.ID = td.SpellID"},{"name":"v_talentos_forever","sql":"CREATE VIEW \"v_talentos_forever\" AS\n        SELECT t.node_id AS NodeID, vt.TreeID, vt.SpellID, vt.Name_esES AS nombre_es, vt.Name_enUS AS nombre_en,\n               t.class_id, c.Name_male_lang_esES AS clase_es, c.Name_lang AS clase_en, t.class_slug,\n               COALESCE(tab.Name_lang_esES, t.tree_name) AS rama_es, t.tree_name AS rama_en, t.tree_slug,\n               t.required_points AS puntos_requeridos,\n               t.required_talent_node_id AS talento_previo_node_id, pv.Name_esES AS talento_previo_es,\n               pv.Name_enUS AS talento_previo_en,\n               t.max_rank, vt.MaxRanks AS max_rank_cliente, t.change AS cambio,\n               sp.Description_lang_esES AS descripcion_es, sp.Description_lang AS descripcion_en_cliente,\n               vt.PosX, vt.PosY, t.version, t.build\n          FROM ext_icy_talentos t\n          JOIN v_talentos vt ON vt.NodeID = t.node_id\n          LEFT JOIN ChrClasses c ON c.ID = t.class_id\n          LEFT JOIN TalentTab tab ON tab.ClassMask = (1 << (t.class_id - 1))\n                                 AND (tab.Name_lang = t.tree_name OR t.tree_name LIKE tab.Name_lang || ' %')\n          LEFT JOIN v_talentos pv ON pv.NodeID = t.required_talent_node_id\n          LEFT JOIN Spell sp ON sp.ID = vt.SpellID"},{"name":"v_vendedor_objeto","sql":"CREATE VIEW \"v_vendedor_objeto\" AS\n        SELECT mv.npc_id, COALESCE(nl.name, n.name, mv.nombre_en) AS npc_nombre, COALESCE(n.name, mv.nombre_en) AS npc_nombre_en,\n               mv.item_id, COALESCE(il.name, s.Display_lang_esES, s.Display_lang) AS objeto, mv.precio, mv.existencias,\n               mv.coste_extra, r.faccion_id, fa.Name_lang_esES AS faccion, r.rep_min AS reputacion_minima, 'forever' AS origen\n          FROM man_vendedor_objeto mv\n          LEFT JOIN man_vendedor_rep r ON r.npc_id = mv.npc_id AND r.item_id = mv.item_id\n          LEFT JOIN Faction fa ON fa.ID = r.faccion_id\n          LEFT JOIN questie_npc n ON n.ID = mv.npc_id\n          LEFT JOIN ext_npc_l10n nl ON nl.npc_id = mv.npc_id AND nl.locale = 'esES'\n          LEFT JOIN ItemSparse s ON s.ID = mv.item_id\n          LEFT JOIN ext_item_l10n il ON il.item_id = mv.item_id AND il.locale = 'esES'"},{"name":"v_zona_faccion","sql":"CREATE VIEW \"v_zona_faccion\" AS\n        SELECT a.ID AS zone_id, a.AreaName_lang_esES AS zona, a.AreaName_lang AS zona_en,\n               CASE WHEN c.faccion IS NOT NULL THEN 'ciudad'\n                    WHEN EXISTS (SELECT 1 FROM LFGDungeons l WHERE l.TypeID = 0 AND (l.Name_lang = a.AreaName_lang\n                                  OR 'The ' || l.Name_lang = a.AreaName_lang)) THEN 'mazmorra'\n                    ELSE 'zona' END AS tipo,\n               COALESCE(c.faccion, CASE a.FactionGroupMask WHEN 2 THEN 'Alianza' WHEN 4 THEN 'Horda' ELSE 'Disputada' END)\n                    AS faccion,\n               CASE WHEN c.faccion IS NOT NULL THEN 'manual' ELSE 'db2' END AS origen\n          FROM AreaTable a LEFT JOIN man_zonas_ciudades c ON c.area_id = a.ID\n         WHERE a.ParentAreaID = 0 AND a.AreaName_lang_esES IS NOT NULL"},{"name":"v_zona_niveles","sql":"CREATE VIEW \"v_zona_niveles\" AS\n        WITH l AS (\n            SELECT s.zone_id, n.maxLevel AS nivel\n              FROM questie_spawn s JOIN questie_npc n ON n.ID = s.entity_id\n             WHERE s.kind = 'npc' AND n.maxLevel BETWEEN 1 AND 60 AND n.maxLevel - n.minLevel <= 3\n               AND n.friendlyToFaction IS NULL\n        ), r AS (\n            SELECT zone_id, nivel, ROW_NUMBER() OVER (PARTITION BY zone_id ORDER BY nivel) AS rn,\n                   COUNT(*) OVER (PARTITION BY zone_id) AS c FROM l\n        )\n        SELECT r.zone_id AS area_id, a.AreaName_lang_esES AS nombre, a.AreaName_lang AS nombre_en,\n               CASE a.FactionGroupMask WHEN 2 THEN 'Alianza' WHEN 4 THEN 'Horda' ELSE 'Disputada' END AS faccion,\n               (SELECT COUNT(*) FROM questie_spawn s JOIN questie_npc n ON n.ID = s.entity_id\n                 WHERE s.kind = 'npc' AND s.zone_id = r.zone_id AND n.friendlyToFaction = 'A') AS pnj_amigos_alianza,\n               (SELECT COUNT(*) FROM questie_spawn s JOIN questie_npc n ON n.ID = s.entity_id\n                 WHERE s.kind = 'npc' AND s.zone_id = r.zone_id AND n.friendlyToFaction = 'H') AS pnj_amigos_horda,\n               CASE WHEN r.zone_id IN (SELECT area_id FROM ext_dungeons) THEN 1 ELSE 0 END AS es_mazmorra,\n               MIN(CASE WHEN rn >= c * 0.05 THEN nivel END) AS nivel_min,\n               MAX(CASE WHEN rn <= c * 0.95 THEN nivel END) AS nivel_max, MAX(c) AS pnj,\n               'deducido' AS origen\n          FROM r LEFT JOIN AreaTable a ON a.ID = r.zone_id\n         GROUP BY r.zone_id HAVING MAX(c) >= 10"}],"indexes":[{"name":"idx_Achievement_Category_ID","sql":"CREATE INDEX \"idx_Achievement_Category_ID\" ON \"Achievement_Category\" (\"ID\")"},{"name":"idx_Achievement_ID","sql":"CREATE INDEX \"idx_Achievement_ID\" ON \"Achievement\" (\"ID\")"},{"name":"idx_AreaTable_ID","sql":"CREATE INDEX \"idx_AreaTable_ID\" ON \"AreaTable\" (\"ID\")"},{"name":"idx_AreaTrigger_ID","sql":"CREATE INDEX \"idx_AreaTrigger_ID\" ON \"AreaTrigger\" (\"ID\")"},{"name":"idx_BattlemasterList_ID","sql":"CREATE INDEX \"idx_BattlemasterList_ID\" ON \"BattlemasterList\" (\"ID\")"},{"name":"idx_BroadcastText_ID","sql":"CREATE INDEX \"idx_BroadcastText_ID\" ON \"BroadcastText\" (\"ID\")"},{"name":"idx_CharTitles_ID","sql":"CREATE INDEX \"idx_CharTitles_ID\" ON \"CharTitles\" (\"ID\")"},{"name":"idx_ChrClassesXPowerTypes_ID","sql":"CREATE INDEX \"idx_ChrClassesXPowerTypes_ID\" ON \"ChrClassesXPowerTypes\" (\"ID\")"},{"name":"idx_ChrClasses_ID","sql":"CREATE INDEX \"idx_ChrClasses_ID\" ON \"ChrClasses\" (\"ID\")"},{"name":"idx_ChrRaceRacialAbility_ID","sql":"CREATE INDEX \"idx_ChrRaceRacialAbility_ID\" ON \"ChrRaceRacialAbility\" (\"ID\")"},{"name":"idx_ChrRaces_ID","sql":"CREATE INDEX \"idx_ChrRaces_ID\" ON \"ChrRaces\" (\"ID\")"},{"name":"idx_ChrSpecialization_ID","sql":"CREATE INDEX \"idx_ChrSpecialization_ID\" ON \"ChrSpecialization\" (\"ID\")"},{"name":"idx_CreatureDifficulty_ID","sql":"CREATE INDEX \"idx_CreatureDifficulty_ID\" ON \"CreatureDifficulty\" (\"ID\")"},{"name":"idx_CreatureDisplayInfo_ID","sql":"CREATE INDEX \"idx_CreatureDisplayInfo_ID\" ON \"CreatureDisplayInfo\" (\"ID\")"},{"name":"idx_CreatureFamily_ID","sql":"CREATE IN